PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT ?paper ?paperLabel ?heightValue ?heightUnitLabel WHERE {
  ?paper orkgp:P31 ?contribution .
  ?contribution a orkgc:C92000 .
  ?contribution orkgp:P71179 ?heightNode .
  ?heightNode orkgp:P71048 ?heightValue .
  OPTIONAL {
    ?heightNode orkgp:P42000 ?heightUnit .
    OPTIONAL { ?heightUnit orkgp:unitLabel ?heightUnitLabel }
  }
  OPTIONAL { ?paper rdfs:label ?paperLabel }
} ORDER BY ?paperLabel ?heightValue

